-- Reproducible demo reset. ONLY fixed synthetic account/record IDs below.
-- Run after the private account setup; existing real users/ideas remain intact.
-- Re-running replaces demonstration votes/comments/history permanently.
begin;
-- Replace these four example addresses with the actual confirmed accounts.
create temporary table demo_people(purpose text primary key,user_id uuid not null) on commit drop;
) as x(purpose,email) join auth.users u on lower(u.email)=lower(x.email) where u.email_confirmed_at is not null;
do $$ begin
 if (select count(*) from demo_people)<>4 then raise exception 'Укажи email четырёх зарегистрированных и подтверждённых аккаунтов.'; end if;
 if not exists(select 1 from demo_people d join public.profiles p on p.id=d.user_id where d.purpose='moderator' and p.role in ('moderator','admin')) then raise exception 'Назначь модератора через аккаунт администратора.'; end if;
end; $$;
delete from public.status_history where idea_id between -91007 and -91001;
delete from public.votes where idea_id between -91007 and -91001;
delete from public.comments where idea_id between -91007 and -91001;
update public.ideas set deleted_at=now(),deleted_reason='Демонстрация скрытой идеи и сохранности связанных записей',deleted_by=(select user_id from demo_people where purpose='moderator') where id=-91007;
commit;
